def encode_resp(val):
    if val is None:
        return b'$-1\r\n'
    if isinstance(val, bool):
        return b':1\r\n' if val else b':0\r\n'
    if isinstance(val, int):
        return f':{val}\r\n'.encode('utf-8')
    if isinstance(val, str):
        b = val.encode('utf-8')
        return f'${len(b)}\r\n'.encode('utf-8') + b + b'\r\n'
    if isinstance(val, list):
        header = f'*{len(val)}\r\n'.encode('utf-8')
        return header + b''.join(encode_resp(item) for item in val)
    raise TypeError(f'Unsupported type {type(val)}')

def decode_resp(data: bytes):
    if not data:
        raise ValueError('Empty buffer')
    prefix = chr(data[0])
    crlf = data.find(b'\r\n')
    if crlf == -1:
        raise ValueError('Incomplete RESP payload')
    line = data[1:crlf].decode('utf-8')
    rest = data[crlf + 2:]

    if prefix == '+':
        return line, rest
    elif prefix == ':':
        return int(line), rest
    elif prefix == '$':
        length = int(line)
        if length == -1:
            return None, rest
        if len(rest) < length + 2:
            raise ValueError('Incomplete bulk string')
        content = rest[:length].decode('utf-8')
        return content, rest[length + 2:]
    elif prefix == '*':
        count = int(line)
        if count == -1:
            return None, rest
        items = []
        for _ in range(count):
            item, rest = decode_resp(rest)
            items.append(item)
        return items, rest
    raise ValueError(f'Unknown RESP prefix: {prefix}')
